export default function ValuationCard({ data }) {
  if (!data) return null;

  const isML = data.prediction_method === "random_forest";

  return (
    <div className="card valuation-result-card">
      <div className="valuation-result-header">
        <div>
          <h3>Recycling Value</h3>

          <p className="muted">
            {isML
              ? "Predicted using the trained Random Forest model."
              : "Calculated using the reference recycling rate."}
          </p>
        </div>

        {isML && <span className="model-badge">ML Prediction</span>}
      </div>

      <div className="value">₹{Number(data.estimated_value).toFixed(2)}</div>

      <div className="valuation-details">
        <div>
          <span>Material</span>
          <strong>{data.material}</strong>
        </div>

        <div>
          <span>Weight</span>
          <strong>{data.weight_kg} kg</strong>
        </div>

        <div>
          <span>Rate</span>
          <strong>₹{data.rate_per_kg}/kg</strong>
        </div>

        <div>
          <span>Quality Factor</span>
          <strong>{data.quality_factor}</strong>
        </div>
      </div>

      {isML && (
        <p className="valuation-note">
          This value is generated by the trained RandomForestRegressor model.
        </p>
      )}
    </div>
  );
}
